/*
 * «Посмотри в окно» — локальный API для исходной заготовки проекта.
 *
 * 1. Сохраните этот файл под именем window-api.js в той же папке, где лежит
 *    index.html. Проверьте имя и расширение файла после скачивания.
 *
 *    папка проекта/
 *      index.html
 *      window-api.js
 *      scripts/
 *        script.js
 *
 * 2. В конце index.html добавьте первую строку перед существующей второй:
 *    <script src="./window-api.js"></script>
 *    <script src="./scripts/script.js"></script>
 *
 * 3. В исходном scripts/script.js замените строку с адресом API на:
 *    const BASE_URL = '';
 *    Замените fetch(endpoint) на window.localVideoApi.fetch(endpoint),
 *    а fetch(urlToFetch) на window.localVideoApi.fetch(urlToFetch).
 *    В generateFilterRequest замените ${city} на ${encodeURIComponent(city)}.
 *
 * 4. Сохраните файлы. В VS Code откройте папку проекта из шага 1 и запустите
 *    её index.html через «Open with Live Server». При необходимости нажмите
 *    Ctrl+F5. На странице появятся пять карточек. Видео запускается в плеере.
 *
 * Если в консоли 404 или ошибка MIME для window-api.js, откройте адрес файла
 * из сообщения об ошибке. Например, для http://127.0.0.1:5500/index.html это
 * http://127.0.0.1:5500/window-api.js. По этому адресу должен открываться код.
 * При 404 проверьте, что файл лежит рядом с тем index.html, который открыт
 * в браузере, и называется window-api.js (без лишнего расширения или «(1)»).
 *
 * Ролики и превью встроены.
 */
(() => {
  'use strict';

  const scenes = [
    ['Санкт-Петербург', [
      'Утро над каналом. По воде тянется отражение набережной.',
      'Дневной свет на фасадах вдоль канала.',
      'Фонари на набережной отражаются в тёмной воде.',
    ]],
    ['Москва', [
      'Городской проспект в первых лучах солнца.',
      'Движение на широком проспекте среди высоток.',
      'Огни машин на ночном проспекте.',
    ]],
    ['Казань', [
      'Мягкий утренний свет над рекой и башнями.',
      'Облака над башнями и открытой набережной.',
      'Подсвеченные башни у тихой реки.',
    ]],
    ['Екатеринбург', [
      'Раннее утро в сквере у высотных домов.',
      'Зелёный сквер на фоне городских высоток.',
      'Свет в окнах высоток над тёмным сквером.',
    ]],
    ['Нижний Новгород', [
      'С откоса открывается вид на широкую реку.',
      'Дневная панорама реки и дальнего берега.',
      'Огни на берегу под ночным небом.',
    ]],
    ['Владивосток', [
      'Утренний свет над бухтой и вантовым мостом.',
      'Вантовый мост над бухтой в ясный день.',
      'Ночная бухта и огни на мосту.',
    ]],
  ];
  const times = ['morning', 'afternoon', 'night'];
  const catalog = times.flatMap((time, timeIndex) => scenes.map(([city, descriptions], cityIndex) => ({
    id: timeIndex * scenes.length + cityIndex + 1,
    city,
    description: descriptions[timeIndex],
    time_of_day: time,
    mediaKey: `${String(cityIndex + 1).padStart(2, '0')}-${time}`,
  })));

  const mediaUrls = new Map();

  function blobUrl(base64, type) {
    const bytes = Uint8Array.from(atob(base64), (character) => character.charCodeAt(0));
    return URL.createObjectURL(new Blob([bytes], { type }));
  }

  function withMedia({ mediaKey, ...entry }) {
    if (!mediaUrls.has(mediaKey)) {
      const { video, preview } = embeddedMedia[mediaKey];
      mediaUrls.set(mediaKey, {
        video: blobUrl(video, 'video/webm'),
        preview: blobUrl(preview, 'image/jpeg'),
      });
    }

    const { video, preview } = mediaUrls.get(mediaKey);
    return {
      ...entry,
      video: { url: video },
      poster: { url: preview },
      thumbnail: { url: preview },
    };
  }

  function normalizeCity(value) {
    return value.toLowerCase().normalize('NFC').replace(/ё/g, 'е').replace(/[\s\p{Dash_Punctuation}]+/gu, ' ').trim();
  }

  function positiveInteger(value, fallback) {
    const number = Number(value);
    return Number.isSafeInteger(number) && number > 0 ? number : fallback;
  }

  function jsonResponse(data, status = 200) {
    return new Response(JSON.stringify(data), {
      status,
      headers: { 'Content-Type': 'application/json; charset=utf-8' },
    });
  }

  async function fetchVideos(endpoint) {
    const { pathname, searchParams } = new URL(endpoint, 'https://local.invalid');
    if (pathname !== '/api/videos') {
      return jsonResponse({ error: 'Маршрут не найден' }, 404);
    }

    const city = normalizeCity(searchParams.get('filters[city][$containsi]') ?? '');
    const selectedTimes = searchParams.getAll('filters[time_of_day][$eqi]')
      .map((time) => time.trim().toLowerCase());
    const matches = catalog.filter((item) =>
      normalizeCity(item.city).includes(city) &&
      (!selectedTimes.length || selectedTimes.includes(item.time_of_day))
    );

    const page = positiveInteger(searchParams.get('pagination[page]'), 1);
    const pageSize = Math.min(positiveInteger(searchParams.get('pagination[pageSize]'), 5), 100);
    const start = (page - 1) * pageSize;
    return jsonResponse({
      results: matches.slice(start, start + pageSize).map(withMedia),
      pagination: { page, pageSize, pageCount: Math.ceil(matches.length / pageSize), total: matches.length },
    });
  }

  const embeddedMedia = {
    "01-morning": {
      "video": "",
      "preview": ""
    },
    "02-morning": {
      "video": "",
      "preview": ""
    },
    "03-morning": {
      "video": "",
      "preview": ""
    },
    "04-morning": {
      "video": "",
      "preview": ""
    },
    "05-morning": {
      "video": "",
      "preview": ""
    },
    "06-morning": {
      "video": "",
      "preview": ""
    },
    "01-afternoon": {
      "video": "",
      "preview": ""
    },
    "02-afternoon": {
      "video": "",
      "preview": ""
    },
    "03-afternoon": {
      "video": "",
      "preview": ""
    },
    "04-afternoon": {
      "video": "",
      "preview": ""
    },
    "05-afternoon": {
      "video": "",
      "preview": ""
    },
    "06-afternoon": {
      "video": "",
      "preview": ""
    },
    "01-night": {
      "video": "",
      "preview": ""
    },
    "02-night": {
      "video": "",
      "preview": ""
    },
    "03-night": {
      "video": "",
      "preview": ""
    },
    "04-night": {
      "video": "",
      "preview": ""
    },
    "05-night": {
      "video": "",
      "preview": ""
    },
    "06-night": {
      "video": "",
      "preview": ""
    }
  };

  window.localVideoApi = Object.freeze({ fetch: fetchVideos });
})();
